<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('[data-a851-menu]'),n=document.querySelector('[data-a851-nav]');b?.addEventListener('click',()=>n?.classList.toggle('is-open'));document.querySelectorAll('.a851-faq details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.a851-faq details[open]').forEach(o=>{if(o!==d)o.open=false})}))});</script>
